// Writes each language's layer tables and combos from the layout files (layout/<lang>.json), the single
// source of the MonoTypist layout. Node only, no packages.
//
//   node tools/gen-keymap.mjs           write config/boards/shields/v4_2_<lang>/v4_2_<lang>.keymap, .layers.dtsi and .combos.dtsi
//   node tools/gen-keymap.mjs --check   change nothing; exit 1 if a written file differs from what layout/ gives
//
// The keymap of each language includes the two files. The firmware build runs --check, so a hand edit of
// a generated file, or a layout change without regenerating, stops the build.
//
// Every combo "letter key + thumb key" becomes "&lpos <layer> <position>": on press it taps whatever the
// thumb key's layer holds at that position at that moment, so a key changed live in ZMK Studio is also
// what the combo sends. Each combo keeps its own timing; a combo listed with its own "binding" (it did not
// have the &lpos shape) keeps that binding.
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const LAYOUT = path.join(ROOT, 'layout');
const SHIELDS = path.join(ROOT, 'config/boards/shields');
const check = process.argv.includes('--check');

const keyboard = JSON.parse(fs.readFileSync(path.join(LAYOUT, 'keyboard.json'), 'utf8'));
const NAME = Object.fromEntries(keyboard.layers.map((l) => [l.id, l.name]));
const DISPLAY = { base: 'Base', blue: 'Blue', red: 'Red', orange: 'Orange' };
const THUMB = Object.fromEntries(keyboard.thumbs.map((t) => [t.position, t.layer]));
const languages = fs.readdirSync(LAYOUT).filter((f) => /^[a-z]{2}\.json$/.test(f)).map((f) => f.slice(0, 2));

const header = (lang, what) =>
  `/*\n * ${what} of the ${lang.toUpperCase()} MonoTypist, generated by tools/gen-keymap.mjs from layout/${lang}.json.\n` +
  ` * Do not edit this file: change layout/${lang}.json and run "node tools/gen-keymap.mjs".\n */\n\n`;

// One matrix row, in columns padded to the widest binding of the layer.
const rowText = (row, width) => '            ' + row.map((b, i) => (i < row.length - 1 ? b.padEnd(width) : b)).join(' ');

function layers(lang, data) {
  let out = header(lang, 'The layer tables') + 'keymap {\n    compatible = "zmk,keymap";\n';
  for (const id of keyboard.layers.map((l) => l.id)) {
    const rows = data.layers[id];
    const simple = data.simple?.[id] ?? {};
    const width = Math.max(...rows.flat().map((b) => b.length), ...Object.values(simple).map((b) => b.length));
    out += `\n    ${id}_layer {\n        display-name = "${DISPLAY[id]}";\n`;
    if (id === 'base' && data.sensor) out += `        sensor-bindings = <${data.sensor}>;\n`;
    out += '        bindings = <\n';
    rows.forEach((row, r) => {
      const changed = row.some((_, c) => simple[r * keyboard.cols + c] !== undefined);
      if (!changed) { out += rowText(row, width) + '\n'; return; }
      // The "simple" firmware variants (SIMPLE_MODE 1) have their own version of this row.
      const alt = row.map((b, c) => simple[r * keyboard.cols + c] ?? b);
      out += `#if SIMPLE_MODE == 1\n${rowText(alt, width)}\n#else\n${rowText(row, width)}\n#endif\n`;
    });
    out += '        >;\n    };\n';
  }
  return out + '};\n';
}

function combos(lang, data) {
  let out = header(lang, 'The combos') + 'combos {\n    compatible = "zmk,combos";\n\n';
  for (const c of data.combos) {
    const thumb = c.positions.find((p) => THUMB[p]);
    const key = c.positions.find((p) => !THUMB[p]);
    const binding = c.binding ?? `&lpos ${NAME[THUMB[thumb]]} ${key}`;
    const props = [`timeout-ms = <${c.timeoutMs}>`, `key-positions = <${c.positions.join(' ')}>`, `bindings = <${binding}>`, ...(c.other ?? [])];
    if (c.slowRelease) props.push('slow-release');
    out += `    ${c.name} { ${props.join('; ')}; };\n`;
  }
  return out + '};\n';
}

// The language's keymap: it names its two generated parts and includes the keymap all languages share
// (config/boards/shields/monotypist/monotypist.keymap.dtsi). The paths are relative to that shared file.
const keymap = (lang) =>
  header(lang, 'The keymap') +
  `#define MT_COMBOS "../v4_2_${lang}/v4_2_${lang}.combos.dtsi"\n` +
  `#define MT_LAYERS "../v4_2_${lang}/v4_2_${lang}.layers.dtsi"\n` +
  '#include "../monotypist/monotypist.keymap.dtsi"\n';

let stale = 0;
for (const lang of languages) {
  const data = JSON.parse(fs.readFileSync(path.join(LAYOUT, `${lang}.json`), 'utf8'));
  const dir = path.join(SHIELDS, `v4_2_${lang}`);
  for (const [file, text] of [[`v4_2_${lang}.keymap`, keymap(lang)], [`v4_2_${lang}.layers.dtsi`, layers(lang, data)], [`v4_2_${lang}.combos.dtsi`, combos(lang, data)]]) {
    const where = path.join(dir, file);
    const now = fs.existsSync(where) ? fs.readFileSync(where, 'utf8').replace(/\r\n/g, '\n') : null;
    if (now === text) continue;
    if (check) { console.error(`out of date: ${path.relative(ROOT, where)} (run "node tools/gen-keymap.mjs")`); stale++; }
    else { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(where, text); console.log(`wrote ${path.relative(ROOT, where)}`); }
  }
}
if (check) {
  if (stale) process.exit(1);
  console.log(`generated keymap files match layout/ (${languages.join(', ')})`);
}
